<?php
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/arqwar-identity.php';
login_required_html();
$battleId=(int)($_GET['battle_id']??0);
$battles=rows("SELECT g.id,g.name,s.area,s.name scenario_name,g.ended_at FROM games g JOIN scenarios s ON s.id=g.scenario_id WHERE g.status='finished' ORDER BY COALESCE(g.ended_at,g.created_at) DESC,g.id DESC");
$currentBattle=$battleId?row("SELECT g.id,g.name,s.area,s.name scenario_name,g.ended_at FROM games g JOIN scenarios s ON s.id=g.scenario_id WHERE g.id=?",[$battleId]):null;
if($battleId){
  $ranking=rows("SELECT t.final_rank,t.name alias,t.final_score,t.is_winner,t.sla,t.reputation,t.slot_no,(SELECT COUNT(*) FROM team_game_cards gc WHERE gc.team_id=t.id) cards_played FROM teams t WHERE t.game_id=? AND t.final_score IS NOT NULL ORDER BY t.final_rank ASC,t.final_score DESC,t.slot_no ASC",[$battleId]);
}else{
  $ranking=leaderboard_rows(null);
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ARQWAR · Ranking</title><link href="assets/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/app.css"><link rel="stylesheet" href="assets/css/arqwar-identity.css?v=20261028-2">
</head><body class="gm-body arqwar-glow-bg"><nav class="navbar navbar-dark border-bottom border-secondary-subtle"><div class="container-fluid"><?= arqwar_brand_html('RANKING GENERAL') ?><div class="d-flex gap-2 flex-wrap"><a class="btn btn-sm btn-outline-light" href="index.php">Inicio</a><a class="btn btn-sm btn-outline-info" href="participant-ranking.php">Participantes</a><a class="btn btn-sm btn-outline-success" href="winners.php">Ganadores</a></div></div></nav><main class="container py-4"><div class="d-flex justify-content-between align-items-end flex-wrap gap-3 mb-4"><div><div class="eyebrow">CLASIFICACIÓN</div><h1 class="display-6 fw-bold mb-1"><?= $battleId?'Ranking por batalla':'Ranking general de equipos' ?></h1><p class="text-secondary mb-0"><?= $battleId?'Ahora puedes filtrar por el alias/nombre de la batalla para ver exactamente qué equipos jugaron y en qué puesto terminaron.':'Vista acumulada global. Si quieres saber qué equipos participaron en una batalla específica, usa el filtro de abajo.' ?></p></div><form method="get" class="ranking-filter battle-filter-card"><label>Alias de batalla</label><select class="form-select" name="battle_id" onchange="this.form.submit()"><option value="0">Todas las batallas / acumulado</option><?php foreach($battles as $b):?><option value="<?=$b['id']?>" <?=$battleId===(int)$b['id']?'selected':''?>><?=e($b['name'])?> · <?=e($b['scenario_name'])?></option><?php endforeach;?></select></form></div><?php if($currentBattle):?><div class="panel p-3 mb-4 arq-card battle-summary"><div class="eyebrow"><?=e($currentBattle['area'])?></div><h2 class="h4 mb-1"><?=e($currentBattle['name'])?></h2><p class="text-secondary mb-0">Casuística: <?=e($currentBattle['scenario_name'])?><?php if(!empty($currentBattle['ended_at'])):?> · Finalizada: <?=e($currentBattle['ended_at'])?><?php endif;?></p></div><?php endif;?><?php if(!$ranking):?><div class="panel p-5 text-center">No hay resultados para este filtro.</div><?php else:?><div class="ranking-list"><?php foreach($ranking as $i=>$r):$pos=$battleId?(int)$r['final_rank']:($i+1);?><article class="ranking-row <?=$pos<=3?'podium podium-'.$pos:''?> depth-card arq-card"><div class="ranking-position">#<?=$pos?></div><div class="ranking-team"><b><?=e($r['alias'])?></b><?php if($battleId):?><small><?=$r['cards_played']?> carta(s) jugadas · REP <?= (int)$r['reputation']?> · SLA <?=number_format((float)$r['sla'],2)?>%</small><?php else:?><small><?=$r['games_played']?> partida(s)</small><?php endif;?></div><?php if($battleId):?><div><span>Estado</span><b><?=$r['is_winner']?'🏆 Campeón':'Finalista'?></b></div><div><span>Puntaje final</span><b><?=$r['final_score']?></b></div><div><span>Slot</span><b>#<?=$r['slot_no']?></b></div><div><span>Cartas</span><b><?=$r['cards_played']?></b></div><?php else:?><div><span>Victorias</span><b><?=$r['wins']?></b></div><div><span>Promedio</span><b><?=number_format((float)$r['avg_score'],1)?></b></div><div><span>Mejor</span><b><?=$r['best_score']?></b></div><div><span>Total</span><b><?=$r['total_score']?></b></div><?php endif;?></article><?php endforeach;?></div><?php endif;?></main></body></html>